import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition (float) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
)

# ---------- 2D Average Pooling (float) ----------
avg_pool_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool_2d_kernel(const float* input, float* output,
                                   int batch_size, int channels, int height, int width, int kernel_size) {
    const int b = blockIdx.z;
    const int by = blockIdx.y * blockDim.y + threadIdx.y;
    const int bx = blockIdx.x * blockDim.x + threadIdx.x;

    if (b < batch_size && by < height && bx < width) {
        float sum = 0.0f;
        for (int ky = -kernel_size/2; ky <= kernel_size/2; ++ky) {
            int y = by + ky;
            if (y >= 0 && y < height) {
                for (int kx = -kernel_size/2; kx <= kernel_size/2; ++kx) {
                    int x = bx + kx;
                    if (x >= 0 && x < width) {
                        const float* idx = input + (((b * channels + channels) * height + y) * width + x);
                        sum += *(const float*)idx;
                    }
                }
            }
        }
        output[b * channels * height * width + by * width + bx] = sum / (kernel_size * kernel_size);
    }
}

torch::Tensor avg_pool_2d_cuda(torch::Tensor x) {
    const int batch_size = x.size(0);
    const int channels = x.size(1);
    const int height = x.size(2);
    const int width = x.size(3);

    // Hardcoded kernel size 11
    const int kernel_size = 11;

    auto out_shape = torch::size({batch_size, channels,
                                  (height + 2 * kernel_size - 1) / kernel_size,
                                  (width + 2 * kernel_size - 1) / kernel_size});

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks_x = (out.size(3) + block_size - 1) / block_size;
    const int num_blocks_y = (out.size(2) + block_size - 1) / block_size;
    const int num_blocks_z = batch_size;

    avg_pool_2d_kernel<<<num_blocks_x, block_size, 0,
                         num_blocks_y, block_size, 0,
                         num_blocks_z, block_size, 0>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        kernel_size
    );

    return out;
}
"""

avg_pool_cpp_source = "torch::Tensor avg_pool_2d_cuda(torch::Tensor x);"

avg_pool_kernel_source = avg_pool_kernel_source

avg_pool_2d_cuda_func = load_inline(
    name="avg_pool_2d_cuda",
    cpp_sources=avg_pool_cpp_source,
    cuda_sources=avg_pool_kernel_source,
    functions=["avg_pool_2d_cuda"],
    verbose=True,
)

# ---------- Optimized model ----------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.avg_pool_cuda = avg_pool_2d_cuda_func

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.avg_pool_cuda(x)
